return items.map((item, index) => {
  const d = item.json || {};
  const ahora = new Date();
  const ts = Date.now();
  const fecha = ahora.toISOString().slice(0,19).replace('T',' ');

  const nombre = String(d.nombres_apellidos || '').trim();
  const correo = String(d.correo || '').trim().toLowerCase();
  const dni = String(d.dni || '').trim();
  const tipoActividad = String(d.tipo_actividad || '').trim().toLowerCase();
  const nombreActividad = String(d.nombre_actividad || '').trim();
  const periodo = String(d.periodo || '').trim();
  const observaciones = String(d.observaciones || '').trim();

  return {
    json: {
      id_ejecucion:
        'CERT-SEG-' + ts + '-' + index + '-' + Math.random().toString(36).slice(2,7),
      id_incidente:
        'INC-CERT-' + ts + '-' + index + '-' + Math.random().toString(36).slice(2,7),

      flujo: '06',
      proceso: 'certificados',
      escenario: 'con_seguridad',
      bloque: 'con_seguridad',
      origen_solicitud: 'formulario_cefic',

      nombres_apellidos: nombre,
      remitente_email: correo,
      dni,
      tipo_actividad: tipoActividad,
      nombre_actividad: nombreActividad,
      periodo,
      observaciones,

      tipo_certificado: 'certificado',
      categoria_real: 'pendiente_validacion',

      hora_ingreso: fecha
    }
  };
});

return items.map(item => {
  const j = item.json;

  const emailValido = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(j.remitente_email || ''));
  const dniValido = /^\d{8}$/.test(String(j.dni || ''));
  const actividadValida = ['seminario', 'curso', 'diplomado'].includes(
    String(j.tipo_actividad || '').toLowerCase()
  );

  const camposCompletos = Boolean(
    j.nombres_apellidos &&
    j.remitente_email &&
    j.dni &&
    j.tipo_actividad &&
    j.nombre_actividad &&
    j.periodo
  );

  const longitudesValidas =
    String(j.nombres_apellidos || '').length <= 150 &&
    String(j.remitente_email || '').length <= 150 &&
    String(j.dni || '').length <= 20 &&
    String(j.nombre_actividad || '').length <= 200 &&
    String(j.periodo || '').length <= 50 &&
    String(j.observaciones || '').length <= 2000;

  item.json.email_valido = emailValido;
  item.json.dni_valido = dniValido;
  item.json.actividad_valida = actividadValida;
  item.json.campos_completos = camposCompletos;
  item.json.longitudes_validas = longitudesValidas;

  item.json.origen_valido =
    j.origen_solicitud === 'formulario_cefic' &&
    emailValido;

  item.json.entrada_valida =
    camposCompletos &&
    dniValido &&
    actividadValida &&
    longitudesValidas;

  item.json.control_validacion_origen = true;
  return item;
});

return items.map(item => {
  const j = item.json;

  const texto = [
    j.nombres_apellidos,
    j.remitente_email,
    j.dni,
    j.tipo_actividad,
    j.nombre_actividad,
    j.periodo,
    j.observaciones
  ].map(v => String(v || '')).join(' ').toLowerCase();

  const patrones = [
    { nombre: 'script_html', regex: /<\s*script\b|javascript\s*:/i },
    { nombre: 'sql_union', regex: /\bunion\s+select\b/i },
    { nombre: 'sql_drop', regex: /\bdrop\s+table\b/i },
    { nombre: 'sql_tautologia', regex: /(?:'|")?\s*or\s+1\s*=\s*1/i },
    { nombre: 'comentario_sql', regex: /--\s|\/\*/i },
    { nombre: 'path_traversal', regex: /\.\.\//i }
  ];

  const coincidencias = patrones
    .filter(p => p.regex.test(texto))
    .map(p => p.nombre);

  item.json.patrones_sospechosos = coincidencias;
  item.json.contenido_sospechoso = coincidencias.length > 0;
  item.json.control_filtrado = true;

  return item;
});

return items.map(item => {
  item.json.prompt_groq = `Actúa como analista de ciberseguridad para CEFIC-Perú.

Analiza una solicitud de certificado recibida mediante formulario web.

Clasifica la solicitud ÚNICAMENTE como:
- legitima
- solicitud_sospechosa

Asigna un score de riesgo entero entre 1 y 10.

Considera:
- consistencia de los datos;
- patrones de inyección o contenido malicioso;
- anomalías en los campos;
- observaciones sospechosas;
- resultado de las validaciones previas.

Un correo externo NO es sospechoso por sí solo, porque los alumnos pueden usar correos personales.

Responde EXCLUSIVAMENTE con JSON válido:
{"categoria":"legitima|solicitud_sospechosa","score":1,"justificacion":"texto breve"}

Datos:
Nombres y apellidos: ${item.json.nombres_apellidos}
Correo: ${item.json.remitente_email}
DNI: ${item.json.dni}
Tipo de actividad: ${item.json.tipo_actividad}
Nombre de actividad: ${item.json.nombre_actividad}
Periodo: ${item.json.periodo}
Observaciones: ${item.json.observaciones || '(sin observaciones)'}
Origen válido: ${item.json.origen_valido}
Entrada válida: ${item.json.entrada_valida}
Patrones sospechosos: ${JSON.stringify(item.json.patrones_sospechosos)}`;

  return item;
});

