return items.map(item => {
  const deteccion = new Date(item.json.hora_deteccion.replace(' ','T'));
  const resolucion = new Date(item.json.hora_resolucion.replace(' ','T'));

  item.json.tiempo_respuesta_min = Number(
    ((resolucion - deteccion) / 60000).toFixed(4)
  );

  item.json.estado_ejecucion = 'success';

  // Escape SQL para campos de texto que posteriormente se insertan.
  // Forma parte del filtrado/protección del flujo CON seguridad.
  const sqlSafe = (v) =>
    String(v ?? '')
      .replace(/\\/g, '\\\\')
      .replace(/'/g, "''");

  const campos = [
    'id_ejecucion',
    'id_incidente',
    'flujo',
    'proceso',
    'escenario',
    'bloque',
    'remitente_email',
    'nombres_apellidos',
    'dni',
    'tipo_actividad',
    'nombre_actividad',
    'periodo',
    'observaciones',
    'tipo_certificado',
    'categoria_sistema',
    'categoria_real',
    'nivel',
    'accion_ejecutada'
  ];

  for (const campo of campos) {
    item.json[campo + '_sql'] = sqlSafe(item.json[campo]);
  }

  item.json.control_registro = true;
  item.json.control_trazabilidad = true;

  return item;
});
